import type { Stable } from "./Stable";

export class HorseBook {
	constructor(private readonly stable: Stable) {}

	get capacity(): number { return this.stable.capacity; }
	get unlockedCount(): number { return this.stable.horses.length; }
	get canUnlock(): boolean { return this.stable.canUnlock; }

	get entries() {
		const horses = this.stable.horses;
		return Array.from({ length: this.capacity }, (_, index) => {
			const horse = horses.find((horse) => horse.variant === index + 1);
			return { variant: index + 1, unlocked: !!horse, name: horse?.name ?? "?", request: horse?.needs.currentRequest ?? null };
		});
	}

	unlockHorse(): void { this.stable.unlockHorse(); }
}
