import type { KAPLAYCtx } from "kaplay";
import type { Point } from "./Geometry";
import type { PastureCamera } from "./PastureCamera";

export class PastureCameraView {
	constructor(private readonly k: KAPLAYCtx, readonly model: PastureCamera) {}

	get scale(): number {
		return this.model.zoom * this.k.canvas.getBoundingClientRect().width / this.k.width();
	}

	clientToWorld(x: number, y: number): Point {
		const rect = this.k.canvas.getBoundingClientRect();
		return this.model.screenToWorld({
			x: (x - rect.left) * this.k.width() / rect.width,
			y: (y - rect.top) * this.k.height() / rect.height,
		});
	}

	worldToClient(point: Point): Point {
		const rect = this.k.canvas.getBoundingClientRect();
		const screen = this.model.worldToScreen(point);
		return { x: rect.left + screen.x * rect.width / this.k.width(), y: rect.top + screen.y * rect.height / this.k.height() };
	}

	pan(dx: number, dy: number): void {
		const rect = this.k.canvas.getBoundingClientRect();
		this.model.pan(dx * this.k.width() / rect.width, dy * this.k.height() / rect.height);
	}

	zoomAt(value: number, x?: number, y?: number): void {
		const anchor = x !== undefined && y !== undefined ? this.model.worldToScreen(this.clientToWorld(x, y)) : undefined;
		this.model.setZoom(value, anchor);
	}

	render(): void {
		this.k.camPos(this.model.position.x, this.model.position.y);
		this.k.camScale(this.model.zoom);
	}
}
