import type { GameObj, KAPLAYCtx } from "kaplay";
import type { Horse } from "./Horse";
import type { HorseSprites } from "./SpriteFactory";

export class HorseView {
	readonly obj: GameObj;
	private readonly mouthObj: GameObj;
	private animation = "";

	constructor(private readonly k: KAPLAYCtx, private readonly horse: Horse, private readonly sprites: HorseSprites) {
		this.obj = k.add([
			k.pos(horse.position.x, horse.position.y),
			k.sprite(sprites[horse.state][horse.direction], { anim: horse.state, width: horse.size }),
		]);
		// Collision child at the mouth (local coords are unscaled 0-100).
		this.mouthObj = this.obj.add([
			k.pos(),
			k.area({ shape: new k.Rect(k.vec2(-8, -8), 16, 16) }),
		]);
		this.render();
	}

	isInEatRange(target: GameObj): boolean {
		return this.mouthObj.isOverlapping(target);
	}

	render(): void {
		const horse = this.horse;
		this.obj.pos = this.k.vec2(horse.position.x, horse.position.y);
		const mouth = horse.mouthPosition;
		this.mouthObj.pos = this.k.vec2(mouth.x - horse.position.x, mouth.y - horse.position.y);
		const animation = `${horse.state}-${horse.direction}`;
		if (animation === this.animation) return;
		this.animation = animation;
		this.obj.use(this.k.sprite(this.sprites[horse.state][horse.direction], { width: horse.size }));
		this.obj.play(horse.state);
	}
}
