import type { KAPLAYCtx } from "kaplay";
import type { Bounds } from "./Geometry";

export class PastureSceneryView {
	private planted = false;
	private readonly decorations = [
		{ sprite: "pasture-tree", emoji: "🌳", size: 112 },
		{ sprite: "pasture-pine", emoji: "🌲", size: 104 },
		{ sprite: "pasture-grass", emoji: "🌿", size: 48 },
		{ sprite: "pasture-sprout", emoji: "🌱", size: 40 },
	];

	constructor(private readonly k: KAPLAYCtx, private readonly bounds: Bounds, private readonly random: () => number = Math.random) {
		for (const decoration of this.decorations) {
			const canvas = document.createElement("canvas");
			canvas.width = 128;
			canvas.height = 128;
			const context = canvas.getContext("2d");
			if (!context) throw new Error("Cannot create pasture emoji textures");
			context.font = '96px "Apple Color Emoji", "Segoe UI Emoji", sans-serif';
			context.textAlign = "center";
			context.textBaseline = "middle";
			context.fillText(decoration.emoji, 64, 68);
			k.loadSprite(decoration.sprite, canvas);
		}
	}

	render(): void {
		if (this.planted) return;
		this.planted = true;
		const { k, bounds } = this;
		const spacing = 160;
		for (let y = bounds.top + 80; y < bounds.bottom - 80; y += spacing) {
			for (let x = bounds.left + 80; x < bounds.right - 80; x += spacing) {
				if (this.random() < 0.3) continue;
				const position = k.vec2(x + (this.random() - 0.5) * 64, y + (this.random() - 0.5) * 64);
				const tree = this.random() < 0.18;
				const decoration = this.decorations[(tree ? 0 : 2) + Math.floor(this.random() * 2)];
				if (!tree) {
					k.add([
						k.pos(position), k.anchor("center"),
						k.rect(104 + this.random() * 24, 76 + this.random() * 24, { radius: 18 }),
						k.color(this.random() < 0.5 ? "#a6c77b" : "#6f9f60"),
						k.opacity(0.3), k.z(-21),
					]);
				}
				k.add([
					k.pos(position), k.anchor("center"),
					k.sprite(decoration.sprite, { width: decoration.size * (0.85 + this.random() * 0.3) }),
					k.z(-20),
				]);
			}
		}
	}
}
