import { clamp, type Point, type Bounds } from "./Geometry";

export class PastureCamera {
	private center: Point;
	private scale = 1;
	private overview = true;

	constructor(readonly bounds: Bounds, private width: number, private height: number) {
		this.center = { x: 0, y: 0 };
		this.fit();
	}

	get position(): Point { return this.center; }
	get zoom(): number { return this.scale; }

	resize(width: number, height: number): void {
		this.width = width;
		this.height = height;
		if (this.overview) this.fit();
		else this.constrain();
	}

	screenToWorld(point: Point): Point {
		return { x: this.center.x + (point.x - this.width / 2) / this.scale, y: this.center.y + (point.y - this.height / 2) / this.scale };
	}

	worldToScreen(point: Point): Point {
		return { x: (point.x - this.center.x) * this.scale + this.width / 2, y: (point.y - this.center.y) * this.scale + this.height / 2 };
	}

	pan(dx: number, dy: number): void {
		this.overview = false;
		this.center = { x: this.center.x + dx / this.scale, y: this.center.y + dy / this.scale };
		this.constrain();
	}

	fit(): void {
		this.overview = true;
		this.center = { x: (this.bounds.left + this.bounds.right) / 2, y: (this.bounds.top + this.bounds.bottom) / 2 };
		this.scale = this.fitScale;
		this.constrain();
	}

	setZoom(value: number, anchor?: Point): void {
		if (!Number.isFinite(value) || value <= 0) return;
		const before = anchor ? this.screenToWorld(anchor) : null;
		this.overview = false;
		this.scale = clamp(value, Math.min(0.2, this.fitScale), 2.5);
		if (before && anchor) {
			const after = this.screenToWorld(anchor);
			this.center = { x: this.center.x + before.x - after.x, y: this.center.y + before.y - after.y };
		}
		this.constrain();
	}

	private get fitScale(): number {
		return Math.min(this.width / (this.bounds.right - this.bounds.left + 48), this.height / (this.bounds.bottom - this.bounds.top + 48));
	}

	private constrain(): void {
		const axis = (value: number, min: number, max: number, half: number) => max - min <= half * 2
			? (min + max) / 2 : clamp(value, min + half - 24, max - half + 24);
		this.center = {
			x: axis(this.center.x, this.bounds.left, this.bounds.right, this.width / this.scale / 2),
			y: axis(this.center.y, this.bounds.top, this.bounds.bottom, this.height / this.scale / 2),
		};
	}
}
