export class CareRub {
	private activeMilliseconds = 0;
	private reversals = 0;
	private direction = 0;
	private strokeDistance = 0;
	private reversalDistance = 0;
	private previous: { x: number; y: number; time: number } | null = null;

	get progress(): number {
		return Math.min(1, this.activeMilliseconds / 3000, (this.reversals + 1) / 5);
	}

	start(x: number, y: number, time: number): void {
		this.previous = { x, y, time };
		this.direction = 0;
		this.strokeDistance = 0;
		this.reversalDistance = 0;
	}

	stop(): void {
		this.previous = null;
		this.direction = 0;
		this.strokeDistance = 0;
		this.reversalDistance = 0;
	}

	move(x: number, y: number, time: number, inside: boolean): void {
		const previous = this.previous;
		if (!previous) return;
		this.previous = { x, y, time };
		const dx = x - previous.x;
		const dy = y - previous.y;
		const elapsed = Math.min(100, Math.max(0, time - previous.time));
		if (!inside) {
			this.direction = 0;
			this.strokeDistance = 0;
			this.reversalDistance = 0;
			return;
		}
		if (dx === 0 || Math.abs(dx) * 2 < Math.abs(dy) || elapsed === 0) return;
		const direction = Math.sign(dx);
		if (this.direction === 0) this.direction = direction;
		if (direction === this.direction) {
			this.strokeDistance += Math.abs(dx);
			this.reversalDistance = 0;
		} else {
			this.reversalDistance += Math.abs(dx);
			if (this.reversalDistance >= 8) {
				if (this.strokeDistance >= 12) this.reversals++;
				this.direction = direction;
				this.strokeDistance = this.reversalDistance;
				this.reversalDistance = 0;
			}
		}
		this.activeMilliseconds += Math.min(elapsed, Math.abs(dx) / 0.06);
	}
}
