import type { HorseBook } from "./HorseBook";
import { CARE_LABELS } from "./CarePresentation";

export class HorseBookView {
	private readonly dialog = document.querySelector<HTMLDialogElement>("#horse-book")!;
	private readonly openButton = document.querySelector<HTMLButtonElement>("#open-horse-book")!;
	private readonly closeButton = document.querySelector<HTMLButtonElement>("#close-horse-book")!;
	private readonly list = document.querySelector<HTMLUListElement>("#horse-list")!;
	private readonly count = document.querySelector<HTMLElement>("#horse-count")!;
	private readonly unlockButton = document.querySelector<HTMLButtonElement>("#unlock-horse")!;
	private readonly slots;

	constructor(private readonly model: HorseBook) {
		this.slots = Array.from({ length: model.capacity }, (_, index) => {
			const item = document.createElement("li");
			item.className = "horse-slot locked";
			const preview = document.createElement("span");
			preview.className = "horse-preview";
			preview.style.backgroundImage = `url(./sprites/horse/${index + 1}.png)`;
			preview.setAttribute("aria-hidden", "true");
			const label = document.createElement("span");
			label.className = "horse-name";
			const status = document.createElement("small");
			item.append(preview, label, status);
			this.list.append(item);
			return { item, preview, label, status };
		});
		this.openButton.addEventListener("click", () => this.dialog.showModal());
		this.closeButton.addEventListener("click", () => this.dialog.close());
		this.dialog.addEventListener("close", () => this.openButton.focus());
		this.unlockButton.addEventListener("click", () => model.unlockHorse());
		this.render();
	}

	render(): void {
		for (const [index, entry] of this.model.entries.entries()) {
			const slot = this.slots[index];
			slot.item.classList.toggle("locked", !entry.unlocked);
			slot.preview.textContent = entry.unlocked ? "" : "?";
			slot.label.textContent = entry.name;
			slot.status.textContent = entry.unlocked ? (entry.request ? CARE_LABELS[entry.request] : "Na pastwisku") : "Zablokowany";
		}
		this.count.textContent = `${this.model.unlockedCount} / ${this.model.capacity}`;
		this.unlockButton.disabled = !this.model.canUnlock;
		this.unlockButton.textContent = this.model.unlockedCount === this.model.capacity
			? "Wszystkie konie odblokowane"
			: "Odblokuj kolejnego konia";
	}
}
