import type { Point } from "./Geometry";
import type { PastureCameraView } from "./PastureCameraView";

export class PastureCameraController {
	private readonly pointers = new Map<number, Point>();
	private readonly controls = document.createElement("nav");

	constructor(private readonly canvas: HTMLCanvasElement, private readonly view: PastureCameraView) {
		this.controls.className = "pasture-controls";
		this.controls.setAttribute("aria-label", "Pasture camera");
		for (const [label, title, action] of [
			["−", "Zoom out", () => view.zoomAt(view.model.zoom / 1.25)],
			["⌂", "Show whole pasture", () => view.model.fit()],
			["+", "Zoom in", () => view.zoomAt(view.model.zoom * 1.25)],
		] as const) {
			const button = document.createElement("button");
			button.type = "button";
			button.textContent = label;
			button.setAttribute("aria-label", title);
			button.addEventListener("click", action);
			this.controls.append(button);
		}
		document.body.append(this.controls);
	}

	get gesturing(): boolean { return this.pointers.size > 0; }

	attach(): void {
		const canvas = this.canvas;
		canvas.addEventListener("wheel", (event) => {
			event.preventDefault();
			if (event.ctrlKey || event.metaKey || event.deltaX === 0) {
				this.view.zoomAt(this.view.model.zoom * Math.exp(-event.deltaY * 0.002), event.clientX, event.clientY);
			} else {
				this.view.pan(event.deltaX, event.deltaY);
			}
		}, { passive: false });
		canvas.addEventListener("pointerdown", (event) => {
			if (event.defaultPrevented || event.button !== 0) return;
			this.pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
			canvas.setPointerCapture(event.pointerId);
		});
		window.addEventListener("pointermove", (event) => {
			const previous = this.pointers.get(event.pointerId);
			if (!previous) return;
			const next = { x: event.clientX, y: event.clientY };
			const other = [...this.pointers.entries()].find(([id]) => id !== event.pointerId)?.[1];
			if (other) {
				const oldDistance = Math.hypot(previous.x - other.x, previous.y - other.y);
				if (oldDistance > 0) this.view.zoomAt(this.view.model.zoom * Math.hypot(next.x - other.x, next.y - other.y) / oldDistance, (next.x + other.x) / 2, (next.y + other.y) / 2);
			}
			this.view.pan((previous.x - next.x) / (other ? 2 : 1), (previous.y - next.y) / (other ? 2 : 1));
			this.pointers.set(event.pointerId, next);
		});
		for (const type of ["pointerup", "pointercancel", "lostpointercapture"] as const) {
			window.addEventListener(type, (event) => this.pointers.delete(event.pointerId));
		}
		window.addEventListener("blur", () => this.pointers.clear());
	}

}
