import type { PastureCameraView } from "./PastureCameraView";
import { clamp } from "./Geometry";
import type { Horse } from "./Horse";
import type { Stable } from "./Stable";
import { CARE_ACTIONS, type CareAction } from "./HorseNeeds";
import { CARE_LABELS } from "./CarePresentation";

export function setupCarePanel(canvas: HTMLCanvasElement, stable: Stable, camera: PastureCameraView, isNavigating: () => boolean): () => void {
	const hint = document.querySelector<HTMLElement>("#care-hint")!;
	const counters = new Map(CARE_ACTIONS.map((action) => [action, document.querySelector<HTMLElement>(`[data-count="${action}"]`)!]));
	const tools: Record<CareAction, string> = { pet: "🤚", brush: "🪮", feed: "🥕", photo: "📷" };
	const labels = CARE_LABELS;
	const responses: Record<CareAction, string> = {
		pet: "Twój koń cieszy się z głaskania 💕",
		brush: "Sierść lśni! ✨",
		feed: "Smacznego! 🥕",
		photo: "Piękna poza! Zdjęcie zrobione 📷",
	};
	const bubbles = new Map<Horse, HTMLButtonElement>();
	const meters = new Map<Horse, HTMLElement>();
	let activeRub: { horse: Horse; pointerId: number; target: HTMLElement } | null = null;
	const cursors = {} as Record<CareAction, string>;
	for (const action of CARE_ACTIONS) {
		const canvas = document.createElement("canvas");
		canvas.width = 48;
		canvas.height = 48;
		const context = canvas.getContext("2d");
		if (!context) {
			cursors[action] = "pointer";
			continue;
		}
		context.font = '36px "Apple Color Emoji", "Segoe UI Emoji", sans-serif';
		context.textAlign = "center";
		context.textBaseline = "middle";
		context.fillText(tools[action], 24, 24);
		cursors[action] = `url("${canvas.toDataURL()}") 24 24, pointer`;
	}

	function fulfill(horse: Horse): void {
		const action = horse.fulfillRequest();
		if (!action) return;
		const bubble = bubbles.get(horse)!;
		const bounds = bubble.getBoundingClientRect();
		bubble.hidden = true;
		const effect = document.createElement("span");
		effect.className = "care-feedback";
		effect.style.scale = String(camera.scale);
		effect.textContent = { pet: "💕", brush: "✨", feed: "🥕", photo: "📸" }[action];
		if (action === "pet" || action === "brush") {
			effect.textContent = "";
			effect.classList.add("care-progress");
			effect.style.backgroundPosition = "-20px -14px";
		}
		effect.setAttribute("aria-hidden", "true");
		effect.style.left = `${bounds.left + bounds.width / 2}px`;
		effect.style.top = `${bounds.top + bounds.height / 2}px`;
		document.body.append(effect);
		window.setTimeout(() => effect.remove(), 1000);
		hint.textContent = responses[action];
		canvas.style.cursor = "default";
		if (action === "photo") {
			const flash = document.createElement("div");
			flash.className = "photo-flash";
			flash.setAttribute("aria-hidden", "true");
			document.body.append(flash);
			window.setTimeout(() => flash.remove(), 400);
		}
	}

	function horseAt(event: PointerEvent): Horse | undefined {
		return stable.horseAt(camera.clientToWorld(event.clientX, event.clientY));
	}

	function stopRub(): void {
		const active = activeRub;
		if (!active) return;
		activeRub = null;
		active.horse.stopRub();
		if (active.target.hasPointerCapture(active.pointerId)) {
			active.target.releasePointerCapture(active.pointerId);
		}
		canvas.style.cursor = "default";
	}

	function beginCare(horse: Horse, event: PointerEvent): void {
		if (isNavigating() || !event.isPrimary || event.button !== 0 || activeRub) return;
		const action = horse.needs.currentRequest;
		if (!action) return;
		event.preventDefault();
		if (action !== "pet" && action !== "brush") {
			fulfill(horse);
			return;
		}
		const target = event.currentTarget as HTMLElement;
		horse.startRub(event.clientX, event.clientY, event.timeStamp);
		activeRub = { horse, pointerId: event.pointerId, target };
		target.setPointerCapture(event.pointerId);
		canvas.style.cursor = cursors[action];
		hint.textContent = "Przytrzymaj i przesuwaj w lewo i prawo przez kilka sekund ↔️";
	}

	canvas.style.touchAction = "none";
	canvas.addEventListener("pointermove", (event) => {
		if (activeRub) return;
		const action = horseAt(event)?.needs.currentRequest;
		canvas.style.cursor = action ? cursors[action] : "default";
	});
	canvas.addEventListener("pointerdown", (event) => {
		const horse = horseAt(event);
		if (horse) beginCare(horse, event);
	});
	window.addEventListener("pointermove", (event) => {
		const active = activeRub;
		if (!active || event.pointerId !== active.pointerId) return;
		if ((event.buttons & 1) === 0) {
			stopRub();
			return;
		}
		const action = active.horse.needs.currentRequest;
		if (action !== "pet" && action !== "brush") {
			stopRub();
			return;
		}
		const bubble = bubbles.get(active.horse)!;
		const bounds = bubble.getBoundingClientRect();
		const horse = active.horse;
		const topLeft = camera.worldToClient(horse.position);
		const bottomRight = camera.worldToClient({ x: horse.position.x + horse.size, y: horse.position.y + horse.size });
		const x = topLeft.x;
		const y = topLeft.y;
		const width = bottomRight.x - x;
		const height = bottomRight.y - y;
		const inside = event.clientX >= Math.min(bounds.left, x) - 32 * camera.scale
			&& event.clientX <= Math.max(bounds.right, x + width) + 32 * camera.scale
			&& event.clientY >= Math.min(bounds.top, y) - 24 * camera.scale
			&& event.clientY <= Math.max(bounds.bottom, y + height) + 24 * camera.scale;
		active.horse.continueRub(event.clientX, event.clientY, event.timeStamp, inside);
		if (active.horse.careProgress >= 1) {
			stopRub();
			fulfill(active.horse);
		}
	});
	for (const type of ["pointerup", "pointercancel", "lostpointercapture"] as const) {
		window.addEventListener(type, (event) => {
			if (event.pointerId === activeRub?.pointerId) stopRub();
		});
	}
	window.addEventListener("blur", stopRub);
	document.addEventListener("visibilitychange", () => {
		if (document.hidden) stopRub();
	});

	return () => {
		const bounds = canvas.getBoundingClientRect();
		const scale = camera.scale;
		const counts: Record<CareAction, number> = { pet: 0, brush: 0, feed: 0, photo: 0 };
		for (const horse of stable.horses) {
			let bubble = bubbles.get(horse);
			if (!bubble) {
				bubble = document.createElement("button");
				bubble.type = "button";
				bubble.className = "horse-request";
				bubble.hidden = true;
				const icon = document.createElement("span");
				icon.className = "request-icon";
				icon.setAttribute("aria-hidden", "true");
				const meter = document.createElement("span");
				meter.className = "care-progress";
				meter.setAttribute("role", "progressbar");
				meter.setAttribute("aria-label", "Postęp opieki");
				meter.setAttribute("aria-valuemin", "0");
				meter.setAttribute("aria-valuemax", "100");
				bubble.append(icon, meter);
				meters.set(horse, meter);
				bubble.addEventListener("pointerdown", (event) => beginCare(horse, event));
				bubble.addEventListener("click", (event) => {
					if (event.detail !== 0) return;
					const action = horse.needs.currentRequest;
					if (action === "pet" || action === "brush") {
						hint.textContent = "Przytrzymaj konia lub dymek i przesuwaj w lewo i prawo ↔️";
					} else if (action) {
						fulfill(horse);
					}
				});
				document.body.append(bubble);
				bubbles.set(horse, bubble);
			}
			const action = horse.needs.currentRequest;
			bubble.hidden = !action;
			if (!action) continue;
			counts[action]++;
			bubble.querySelector<HTMLElement>(".request-icon")!.textContent = tools[action];
			const needsRub = action === "pet" || action === "brush";
			const meter = meters.get(horse)!;
			meter.hidden = !needsRub;
			const progress = horse.careProgress;
			const hearts = progress > 0 ? Math.ceil(progress * 6) : 0;
			meter.style.backgroundPosition = `-20px -${14 + (6 - Math.max(1, hearts)) * 48}px`;
			meter.style.filter = hearts === 0 ? "grayscale(1)" : "none";
			meter.style.opacity = hearts === 0 ? "0.5" : "1";
			meter.setAttribute("aria-valuenow", String(Math.round(progress * 100)));
			bubble.classList.toggle("is-rubbing", activeRub?.horse === horse);
			if (activeRub?.horse === horse) {
				hint.textContent = `${labels[action]}: ${Math.round(progress * 100)}% — przesuwaj w lewo i prawo ↔️`;
			}
			bubble.setAttribute("aria-label", `${horse.name}: ${labels[action]}. ${needsRub ? "Przytrzymaj i przesuwaj w lewo i prawo." : "Kliknij, aby pomóc."}`);
			bubble.style.cursor = cursors[action];
			const position = camera.worldToClient({ x: horse.position.x + horse.size / 2, y: horse.position.y + 10 });
			const foot = camera.worldToClient({ x: horse.position.x + horse.size / 2, y: horse.position.y + horse.size });
			const visible = position.x >= bounds.left && position.x <= bounds.right
				&& position.y >= bounds.top && foot.y <= bounds.bottom;
			bubble.hidden = !visible;
			bubble.style.setProperty("--camera-scale", String(scale));
			const halfWidth = (Math.max(bubble.offsetWidth, needsRub ? 208 : 0) / 2 + 4) * scale;
			const topPadding = (bubble.offsetHeight + (needsRub ? 44 : 0) + 10) * scale;
			bubble.style.left = `${clamp(position.x, bounds.left + halfWidth, Math.max(bounds.left + halfWidth, bounds.right - halfWidth))}px`;
			bubble.style.top = `${Math.max(bounds.top + topPadding, position.y)}px`;
		}
		for (const action of CARE_ACTIONS) {
			counters.get(action)!.textContent = String(counts[action]);
			counters.get(action)!.closest(".care-action")!.classList.toggle("has-requests", counts[action] > 0);
		}
	};
}
