import { Horse } from "./Horse";
import { HORSE_NEEDS_POLICIES } from "./HorseNeeds";
import type { Bounds, Point } from "./Geometry";

export class Stable {
	private readonly residents: Horse[] = [];
	private readonly names = ["Clover", "Maple", "Poppy", "Mochi", "Willow", "Hazel", "Peaches", "Biscuit", "Sunny", "Cocoa", "Daisy", "Toffee"];

	constructor(private readonly bounds: Bounds, private readonly random: () => number = Math.random) {}

	get horses(): readonly Horse[] { return this.residents.slice(); }
	get capacity(): number { return HORSE_NEEDS_POLICIES.length; }
	get canUnlock(): boolean { return this.residents.length < this.capacity; }

	horseAt(point: Point): Horse | undefined {
		return [...this.residents].reverse().find((horse) => horse.contains(point));
	}

	unlockHorse(): Horse | null {
		if (!this.canUnlock) return null;
		const index = this.residents.length;
		const maxX = Math.max(0, this.bounds.right - 200);
		const maxY = Math.max(0, this.bounds.bottom - 200);
		const minX = Math.min(this.bounds.left, maxX);
		const minY = Math.min(this.bounds.top, maxY);
		const name = this.names.splice(Math.floor(this.random() * this.names.length), 1)[0];
		const horse = new Horse({ x: minX + this.random() * (maxX - minX), y: minY + this.random() * (maxY - minY) },
			this.bounds, name, index + 1, HORSE_NEEDS_POLICIES[index], 200, this.random);
		this.residents.push(horse);
		return horse;
	}

	update(dt: number): void {
		for (const horse of this.residents) horse.update(dt);
	}
}
