import { HorseState, HorseDirection } from "./enums";
import { CareRub } from "./CareRub";
import { HorseNeeds, HORSE_NEEDS_POLICIES, type CareAction, type HorseNeedsPolicy } from "./HorseNeeds";
import { clamp, type Point, type Bounds } from "./Geometry";

export type HorseRoamingBounds = Bounds;

export class Horse {
	// Sprite frame is 100x100; all world offsets derive from scale.
	static readonly FRAME_SIZE = 100;
	private currentState = HorseState.Idle;
	private facing = HorseDirection.Right;
	private location: Point;
	private moveTarget: Point | null = null;
	private idleTime = 0;
	private actionTime = 0;
	private rub = new CareRub();
	readonly needs: HorseNeeds;
	onEatEnd?: (mouthPos: Point) => void;

	constructor(
		position: Point,
		private readonly roamingBounds: Bounds,
		readonly name = "Horse",
		readonly variant = 1,
		policy: HorseNeedsPolicy = HORSE_NEEDS_POLICIES[0],
		readonly size = 200,
		private readonly random: () => number = Math.random,
	) {
		this.location = { ...position };
		this.needs = new HorseNeeds(policy);
	}

	get position(): Point { return this.location; }
	get state(): HorseState { return this.currentState; }
	get direction(): HorseDirection { return this.facing; }

	get careProgress(): number {
		return this.rub.progress;
	}

	startRub(x: number, y: number, time: number): void {
		if (this.needs.currentRequest !== "pet" && this.needs.currentRequest !== "brush") return;
		this.rub.start(x, y, time);
	}

	stopRub(): void {
		this.rub.stop();
	}

	continueRub(x: number, y: number, time: number, inside: boolean): void {
		if (this.needs.currentRequest !== "pet" && this.needs.currentRequest !== "brush") return;
		this.rub.move(x, y, time, inside);
	}


	moveTo(target: Point): void {
		// pos is top-left of the scaled sprite; center it on the tap.
		const half = this.size / 2;
		this.moveTarget = { x: target.x - half, y: target.y - half };
	}

	fulfillRequest(): CareAction | null {
		const action = this.needs.fulfill();
		if (!action) return null;
		this.rub = new CareRub();
		this.moveTarget = null;
		this.idleTime = 3;
		this.setState(action === "feed" ? HorseState.Eat : action === "photo" ? HorseState.Rear : HorseState.Idle);
		return action;
	}

	soothe(): void {
		if (this.actionTime > 0) return;
		this.moveTarget = null;
		this.idleTime = 3;
		this.setState(HorseState.Idle);
	}

	contains(point: Point): boolean {
		return point.x >= this.location.x + this.size * 0.15 && point.x <= this.location.x + this.size * 0.85
			&& point.y >= this.location.y + this.size * 0.2 && point.y <= this.location.y + this.size * 0.85;
	}

	startEating(): void {
		if (!this.needs.currentRequest && this.actionTime === 0) {
			this.moveTarget = null;
			this.setState(HorseState.Eat);
		}
	}

	update(dt: number): void {
		if (!Number.isFinite(dt) || dt <= 0) return;
		const bounds = this.roamingBounds;
		const maxX = Math.max(0, bounds.right - this.size);
		const maxY = Math.max(0, bounds.bottom - this.size);
		const minX = Math.min(bounds.left, maxX);
		const minY = Math.min(bounds.top, maxY);
		this.location = { x: clamp(this.location.x, minX, maxX), y: clamp(this.location.y, minY, maxY) };
		if (this.actionTime > 0) {
			this.actionTime = Math.max(0, this.actionTime - dt);
			if (this.actionTime === 0) {
				if (this.state === HorseState.Eat) this.onEatEnd?.(this.mouthPosition);
				this.setState(HorseState.Idle);
				this.idleTime = 1 + this.random() * 2;
			}
			return;
		}
		const previousRequest = this.needs.currentRequest;
		this.needs.update(dt);
		if (this.needs.currentRequest) {
			this.moveTarget = null;
			if (!previousRequest) this.setState(HorseState.Rear);
			return;
		}
		if (this.idleTime > 0) {
			this.idleTime -= dt;
			return;
		}
		if (!this.moveTarget) this.moveTarget = { x: minX + this.random() * (maxX - minX), y: minY + this.random() * (maxY - minY) };
		const target = { x: clamp(this.moveTarget.x, minX, maxX), y: clamp(this.moveTarget.y, minY, maxY) };
		const dx = target.x - this.location.x;
		const dy = target.y - this.location.y;
		const distance = Math.hypot(dx, dy);
		const step = 240 * dt;
		if (distance <= step) {
			this.location = target;
			this.moveTarget = null;
			this.idleTime = 1 + this.random() * 2;
			this.setState(HorseState.Idle);
			return;
		}
		this.facing = Math.abs(dx) >= Math.abs(dy)
			? (dx < 0 ? HorseDirection.Left : HorseDirection.Right)
			: (dy < 0 ? HorseDirection.Up : HorseDirection.Down);
		this.location = { x: this.location.x + dx / distance * step, y: this.location.y + dy / distance * step };
		this.setState(HorseState.Walk);
	}

	get mouthPosition(): Point {
		// Mouth sits bottom-right when facing right, mirrored on flipX.
		const offsets = { left: [0.25, 0.6], right: [0.75, 0.6], down: [0.5, 0.65], up: [0.5, 0.4] };
		const [x, y] = offsets[this.direction];
		return { x: this.location.x + x * this.size, y: this.location.y + y * this.size };
	}

	private setState(state: HorseState): void {
		if (this.currentState === state) return;
		this.currentState = state;
		this.actionTime = state === HorseState.Eat ? 3 / 7 : state === HorseState.Rear ? 8 / 7 : 0;
	}
}
