import type { KAPLAYCtx } from "kaplay";
import type { Stable } from "./Stable";
import type { Horse } from "./Horse";
import { HorseView } from "./HorseView";
import { SpriteFactory } from "./SpriteFactory";

export class StableView {
	private readonly horses = new Map<Horse, HorseView>();
	private readonly sprites;

	constructor(private readonly k: KAPLAYCtx, private readonly stable: Stable) {
		const factory = new SpriteFactory(k);
		this.sprites = Array.from({ length: stable.capacity }, (_, index) => factory.createHorse(index + 1));
	}

	render(): void {
		for (const horse of this.stable.horses) {
			let view = this.horses.get(horse);
			if (!view) {
				view = new HorseView(this.k, horse, this.sprites[horse.variant - 1]);
				this.horses.set(horse, view);
			}
			view.render();
		}
	}
}
