import kaplay from "kaplay";
import { Stable } from "./Stable";
import { HorseBook } from "./HorseBook";
import { setupCarePanel } from "./CarePanel";
import { PastureCamera } from "./PastureCamera";
import { PastureCameraView } from "./PastureCameraView";
import { PastureCameraController } from "./PastureCameraController";
import { StableView } from "./StableView";
import { PastureSceneryView } from "./PastureSceneryView";
import { HorseBookView } from "./HorseBookView";
import { pastureBounds } from "./Pasture";
// import "kaplay/global"; // uncomment if you want to use without the k. prefix

const panel = document.querySelector<HTMLElement>(".care-panel")!;
const updatePadding = () => document.documentElement.style.setProperty("--care-space", `${window.innerHeight - panel.getBoundingClientRect().top + 16}px`);
updatePadding();
new ResizeObserver(updatePadding).observe(panel);
window.addEventListener("resize", updatePadding);

const k = kaplay({ background: [139, 181, 115], root: document.querySelector<HTMLElement>("#pasture-viewport")! });

k.loadRoot("./"); // A good idea for Itch.io publishing later

const bounds = pastureBounds(k.width(), k.height());
const stable = new Stable(bounds);
const camera = new PastureCamera(bounds, k.width(), k.height());
const cameraView = new PastureCameraView(k, camera);
const cameraController = new PastureCameraController(k.canvas, cameraView);
const stableView = new StableView(k, stable);
const sceneryView = new PastureSceneryView(k, bounds);

k.onResize(() => camera.resize(k.width(), k.height()));
k.onLoad(() => {
	sceneryView.render();
	stable.unlockHorse();
	const horseBookView = new HorseBookView(new HorseBook(stable));
	const renderCare = setupCarePanel(k.canvas, stable, cameraView, () => cameraController.gesturing);
	cameraController.attach();
	camera.resize(k.width(), k.height());
	cameraView.render();
	stableView.render();
	k.onUpdate(() => {
		stable.update(k.dt());
		cameraView.render();
		stableView.render();
		horseBookView.render();
		renderCare();
	});
});
